mapper.select:
/*menu.selectMenusByAuths*/ SELECT MENU.MENU_ID AS MENUID , MENU.UPPER_ID AS UPPERID , MENU.NAME , MENU.DEPTH , MENU.TYPE , AUTH.AUTH_ID AS AUTHID , MENU.URL , MENU.MENU_ORDER AS MENUORDER , MENU.MENU_DC AS MENUDC , MENU.CREATE_DT AS CREATEDT , SUBSTR(MENU.UPPER_ID,0,4)||'000' AS TOPMENUID FROM KX_MENUINFO MENU , KX_MENUAUTH AUTH WHERE MENU.MENU_ID = AUTH.MENU_ID AND NVL(MENU.USE_FLAG, 'Y') != 'N' AND NVL(AUTH.USE_FLAG, 'Y') != 'N' AND AUTH.AUTH_ID IN
#{item}
ORDER BY MENU.DEPTH ASC , MENU.MENU_ORDER ASC

mapper.update:

	UPDATE		KX_MENUINFO	
	SET 			UPPER_ID =  #{upperId}
					, NAME = #{name}
					, DEPTH = #{depth}
					, TYPE =  #{type}
					, AUTH_ID = #{authId}
					, URL = #{url}
					, MENU_ORDER = #{menuOrder}
					, MENU_DC = #{menuDc}
					, CREATE_DT = sysdate
  	WHERE		MENU_ID = #{menuId}
